// Strategy Engine: Determine optimal logistics mode based on input conditions

const items = $input.all();
const firstItem = items[0].json;

let selected_mode = 'Balanced';
let mode_reason = '';

// Priority 1: Check for new emergency orders
if (firstItem.new_order && firstItem.new_order.priority === 'high') {
  selected_mode = 'Emergency';
  mode_reason = 'New high-priority order detected - prioritizing immediate delivery';
}
// Priority 2: Check fuel level for cost optimization
else if (firstItem.fuel_level !== undefined && firstItem.fuel_level < 30) {
  selected_mode = 'Cost';
  mode_reason = `Low fuel level detected (${firstItem.fuel_level}%) - optimizing for fuel efficiency`;
}
// Priority 3: Check if majority of orders are high priority
else if (firstItem.orders && Array.isArray(firstItem.orders)) {
  const highPriorityCount = firstItem.orders.filter(order => order.priority === 'high').length;
  const totalOrders = firstItem.orders.length;
  const highPriorityPercentage = (highPriorityCount / totalOrders) * 100;

  if (highPriorityPercentage > 50) {
    selected_mode = 'Speed';
    mode_reason = `${highPriorityPercentage.toFixed(1)}% of orders are high priority - optimizing for speed`;
  } else {
    selected_mode = 'Balanced';
    mode_reason = 'Normal operating conditions - using balanced optimization';
  }
}
// Default: Balanced mode
else {
  selected_mode = 'Balanced';
  mode_reason = 'No special conditions detected - using balanced optimization';
}

return [
  {
    json: {
      selected_mode: selected_mode,
      mode_reason: mode_reason,
      ...firstItem
    }
  }
];

// Route Optimizer: Optimize delivery routes based on selected mode

const items = $input.all();
if (!items.length) {
  throw new Error("No input items received");
}

const firstItem = items[0].json;


// ================= PARSE BODY SAFELY =================

let parsedBody = firstItem.body;

if (typeof parsedBody === "string") {
  try {
    parsedBody = JSON.parse(parsedBody);
  } catch {
    parsedBody = {};
  }
}


// ================= BASIC INPUTS =================

const selected_mode = firstItem.selected_mode || "Balanced";

const current_location =
  firstItem.origin_addresses?.[0] ||
  parsedBody?.origin ||
  parsedBody?.current_location ||
  "unknown";

const orders =
  parsedBody?.orders ||
  firstItem.orders ||
  firstItem.data?.orders ||
  [];


// ================= DISTANCE API RESPONSES =================

const apiResponses =
  firstItem.data ||
  firstItem.rows ||
  items.map(i => i.json);


// ================= BUILD DISTANCE DATA =================

const distanceData = apiResponses.map((apiResponse, index) => {

  const order = orders[index] || {};

  let distance_km = 0;

  const element =
    apiResponse?.rows?.[0]?.elements?.[0] ||
    apiResponse?.elements?.[0];

  if (element?.distance?.value) {
    distance_km = element.distance.value / 1000;
  }

  return {
    order_id: order.id ?? index,
    location: order.location ?? order.address ?? null,
    priority: order.priority ?? "medium",
    distance_km,
    visited: false
  };
});


// ================= ROUTE LOGIC =================

let optimized_route = [];
let total_distance_km = 0;


if (selected_mode === "Emergency") {

  const newOrderId = parsedBody?.new_order?.id;

  const newOrder = distanceData.find(d => d.order_id === newOrderId);

  if (newOrder) {
    optimized_route.push(newOrder);
    total_distance_km += newOrder.distance_km;
    newOrder.visited = true;
  }

  while (optimized_route.length < distanceData.length) {
    let nearest = null;
    let minDist = Infinity;

    for (const order of distanceData) {
      if (!order.visited && order.distance_km < minDist) {
        minDist = order.distance_km;
        nearest = order;
      }
    }

    if (!nearest) break;

    optimized_route.push(nearest);
    total_distance_km += nearest.distance_km;
    nearest.visited = true;
  }

}
else if (selected_mode === "Cost") {

  while (optimized_route.length < distanceData.length) {
    let nearest = null;
    let minDist = Infinity;

    for (const order of distanceData) {
      if (!order.visited && order.distance_km < minDist) {
        minDist = order.distance_km;
        nearest = order;
      }
    }

    if (!nearest) break;

    optimized_route.push(nearest);
    total_distance_km += nearest.distance_km;
    nearest.visited = true;
  }

}
else if (selected_mode === "Speed") {

  const high = distanceData
    .filter(o => o.priority === "high")
    .sort((a,b)=>a.distance_km-b.distance_km);

  const normal = distanceData
    .filter(o => o.priority !== "high")
    .sort((a,b)=>a.distance_km-b.distance_km);

  optimized_route = [...high,...normal];

  total_distance_km =
    optimized_route.reduce((s,o)=>s+o.distance_km,0);

}
else {

  const weight = { high:1, medium:2, low:3 };

  const scored = distanceData.map(order=>{
    const priorityScore = weight[order.priority] || 2;
    const score = (order.distance_km * 0.7) + (priorityScore * 0.3);
    return {...order, score};
  });

  optimized_route =
    scored.sort((a,b)=>a.score-b.score);

  total_distance_km =
    optimized_route.reduce((s,o)=>s+o.distance_km,0);
}


// ================= CLEAN OUTPUT =================

const cleanRoute = optimized_route.map(o=>({
  order_id:o.order_id,
  location:o.location,
  priority:o.priority,
  distance_km:o.distance_km
}));


// ================= EXPLANATION ENGINE =================

const explanation =
  selected_mode === "Emergency"
    ? "Emergency mode selected: urgent order first then nearest."
    : selected_mode === "Cost"
    ? "Cost mode selected: shortest path optimization."
    : selected_mode === "Speed"
    ? "Speed mode selected: high priority deliveries first."
    : "Balanced mode selected: weighted scoring using distance + priority.";


// ================= RETURN =================

return [{
  json:{
    selected_mode,
    mode_reason:firstItem.mode_reason || "auto",
    explanation,
    optimized_route: cleanRoute,
    total_distance_km: Math.round(total_distance_km*100)/100,
    current_location,
    fuel_level: parsedBody?.fuel_level ?? null,
    total_orders: cleanRoute.length,
    timestamp: new Date().toISOString()
  }
}];

// Risk Engine: Assess risks based on fuel level, distance, mode, and priorities

const items = $input.all();
const firstItem = items[0].json;

const fuel_level = firstItem.fuel_level;
const total_distance_km = firstItem.total_distance_km;
const selected_mode = firstItem.selected_mode;
const optimized_route = firstItem.optimized_route || [];

let risk_level = 'Low';
const risk_factors = [];

// Risk Assessment Logic

// 1. Fuel Level Risk
if (fuel_level < 15) {
  risk_factors.push({
    type: 'Critical Fuel Level',
    severity: 'High',
    description: `Fuel level at ${fuel_level}% - immediate refueling required`
  });
  risk_level = 'High';
} else if (fuel_level < 30) {
  risk_factors.push({
    type: 'Low Fuel Level',
    severity: 'Medium',
    description: `Fuel level at ${fuel_level}% - refueling recommended`
  });
  if (risk_level !== 'High') {
    risk_level = 'Medium';
  }
}

// 2. Long Route Risk
if (total_distance_km > 200) {
  risk_factors.push({
    type: 'Long Route Distance',
    severity: 'Medium',
    description: `Total route distance of ${total_distance_km} km exceeds 200 km threshold`
  });
  if (risk_level === 'Low') {
    risk_level = 'Medium';
  }
}

// 3. SLA Risk: Cost mode with high priority orders
const highPriorityOrders = optimized_route.filter(order => order.priority === 'high');
if (selected_mode === 'Cost' && highPriorityOrders.length > 0) {
  risk_factors.push({
    type: 'SLA Risk',
    severity: 'Medium',
    description: `Cost optimization mode selected with ${highPriorityOrders.length} high-priority orders - potential delivery delays`
  });
  if (risk_level === 'Low') {
    risk_level = 'Medium';
  }
}

// If no risks detected
if (risk_factors.length === 0) {
  risk_factors.push({
    type: 'No Risks Detected',
    severity: 'Low',
    description: 'All parameters within acceptable ranges'
  });
}

return [
  {
    json: {
      ...firstItem,
      risk_level: risk_level,
      risk_factors: risk_factors
    }
  }
];
